clamp.code:
def clamp(x, lo, hi):
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x

gcd.code:
def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

fib.code:
def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

is_prime.code:
def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True

binary_search.code:
def binary_search(xs, target):
    lo, hi = 0, len(xs) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if xs[mid] == target:
            return mid
        if xs[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

count_vowels.code:
def count_vowels(s):
    count = 0
    for ch in s.lower():
        if ch in "aeiou":
            count += 1
    return count

merge_sorted.code:
def merge_sorted(a, b):
    i, j = 0, 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    while i < len(a):
        out.append(a[i])
        i += 1
    while j < len(b):
        out.append(b[j])
        j += 1
    return out

run_count.code:
def run_count(s):
    if not s:
        return 0
    count = 1
    for i in range(1, len(s)):
        if s[i] != s[i - 1]:
            count += 1
    return count

sum_positive.code:
def sum_positive(xs):
    total = 0
    for x in xs:
        if x > 0:
            total += x
    return total
